window.TRACE_DECK = {"content":{"_ai_assisted":"AI-assisted: written with Claude Code (Anthropic) and maintained with Codex (OpenAI). See docs/AI_USAGE.md.","_note":"Source of truth for the TRACE pitch deck. Edit here, then run: python3 deck/build.py","meta":{"title":"TRACE","event":"2026 Carolina Data Challenge · Graduate Track","theme":"AI for Social Good","runtime_target_seconds":156,"demo_seconds":120,"qa_seconds":120,"format_note":"7:00 total (deck + live demo) + 2:00 Q&A. The live demo follows the deck."},"speakers":[{"slot":"S1","name":"William Keffer","section":"The Problem","seconds":44},{"slot":"S2","name":"Ismail Gasmi","section":"The Idea","seconds":24},{"slot":"S3","name":"Markandeya Yalamanchi","section":"How It Works","seconds":62},{"slot":"S4","name":"Adrian Hito","section":"Proof, Impact & Handoff","seconds":26}],"slides":[{"id":"title","act":"I","speaker":"S1","seconds":0,"theme":"void","layout":"split","blocks":[{"type":"qr","src":"assets/qr-trace-site.svg","caption":"Scan to open the live site","url":"trace-atlas-gules.vercel.app"},{"type":"wordmark","text":"TRACE"},{"type":"lines","scale":"m","items":["{{project.one_liner}}"]},{"type":"source","text":"2026 Carolina Data Challenge · Graduate Track · AI for Social Good"}],"cues":["Leave this up while judges settle in; it gives them time to scan the code.","Advance to the Afghanistan slide to start the clock."]},{"id":"cold-1","act":"I","speaker":"S1","seconds":8,"theme":"void","blocks":[{"type":"photo","variant":"side","src":"assets/slide-1-afghanistan-opium.jpg","alt":"An armed man carrying a rocket launcher walks through a flowering opium poppy field in Afghanistan.","caption":"AFGHANISTAN · OPIUM POPPY FIELD · 2005 FILE PHOTO"},{"type":"lines","scale":"xl","items":["Afghanistan grew four fifths","of the world's illicit opium."]},{"type":"viz","viz":{"kind":"fraction","parts":5,"filled":4,"label":"4 of every 5 kilograms of illicit opium on earth · before 2022"}},{"type":"source","text":"UNODC World Drug Report 2026 · about 80% of global illicit opium production before 2022"}],"cues":["Hold two full seconds of silence before you speak.","Say it flat. The fact does the work.","Four fifths. Not 'most' — the number is the hook.","The photo is a 2005 file image of an Afghan opium poppy field; it sets the scene, it is not TRACE evidence. Photographer credit and reuse permission still need to be confirmed."],"layout":"split"},{"id":"cold-2","act":"I","speaker":"S1","seconds":7,"theme":"void","blocks":[{"type":"lines","scale":"xl","items":["In April 2022, one decree"]},{"type":"lines","scale":"xl","tone":"accent","items":["cut it by 95%."]},{"type":"viz","viz":{"kind":"bars","size":"big","items":[{"label":"2022","value":6200,"text":"6,200 t","tone":"off"},{"label":"2023","value":333,"text":"333 t","tone":"on"}]},"caption":"Afghan opium production, tonnes"},{"type":"source","text":"Taliban decree 3 April 2022, enforced from the 2022/23 planting season · Afghan opium production 6,200 t (2022) → 333 t (2023) · UNODC Afghanistan Opium Survey"}],"cues":["Beat before '95%'.","Be precise if asked: 95% is Afghan *production*, and Afghanistan was ~80% of world supply.","Never say 'erased the world's opium' — about 12,000 tonnes of stockpile kept flowing."]},{"id":"cold-3","act":"I","speaker":"S1","seconds":6,"theme":"void","blocks":[{"type":"lines","scale":"l","items":["The drugs didn't stop."]},{"type":"lines","scale":"xl","tone":"accent","items":["They moved."],"step":1},{"type":"sub","text":"And for three years, nobody could tell the countries they moved toward that they were coming.","step":1,"stepDelay":900}],"cues":["Click once after 'The drugs didn't stop.' to bring in 'They moved.' Let the pause land.","'They moved' is the thesis of the entire project.","Land it, then go straight to the lag slide."],"layout":"center"},{"id":"lag","act":"I","speaker":"S1","seconds":12,"theme":"void","blocks":[{"type":"kicker","text":"The world's drug-harm data, today"},{"type":"lagrow","items":[{"label":"Intentional homicide rate","year":"2022","code":"VC.IHR.PSRC.P5 · 142 of 243 have nothing newer"},{"label":"HIV incidence, 15–49","year":"2024","code":"SH.HIV.INCD.ZS · modelled, not surveyed"},{"label":"Poverty headcount","year":"2022","code":"SI.POV.DDAY · 59% have nothing newer"},{"label":"Cannabis use prevalence","year":"2017","code":"UNODC WDR annex 1.2 · 11 countries have a 2024+ estimate"}]},{"type":"lines","scale":"m","items":["Development data runs two to four years late.","Drug-use prevalence, for the median country,","runs nine."]},{"type":"source","text":"Median economy's most recent value, World Bank Indicators API, retrieved 2026-09-26 · UNODC World Drug Report 2026 statistical annex"}],"cues":["These are median-country figures we pulled from the live API, not the best-reported country.","Nine years is the number to land. Say it and stop.","If challenged: the WDR headline year is 2024, but that rests on estimates most countries last made in 2017."]},{"id":"late-detection","act":"I","speaker":"S1","seconds":11,"theme":"void","blocks":[{"type":"photo","variant":"backdrop","src":"assets/slide-5-austin-march.jpg","alt":"Austin residents march during the 2015 Scott County HIV emergency; a memorial sign is visible.","caption":"AUSTIN · 2015 · SARAH PARVINI / LOS ANGELES TIMES"},{"type":"kicker","text":"What the delay costs"},{"type":"lines","scale":"l","items":["Scott County, Indiana.","HIV spread undetected for four years."]},{"type":"statgrid","compact":true,"items":[{"value":"215","label":"people infected","source":"undetected from 2011; emergency declared 26 March 2015","viz":{"kind":"dots","count":215,"per":1,"label":"one dot = one person"}},{"value":"<56","label":"if caught in 2013","source":"modelled counterfactual","viz":{"kind":"dots","count":56,"per":1}},{"value":"<10","label":"if the 2011 hepatitis C signal had been read","source":"the warning was already in the data","viz":{"kind":"dots","count":10,"per":1}}]},{"type":"sub","text":"This is the pattern, not the exception. In three of four documented outbreaks a hepatitis C or injecting signal preceded the HIV outbreak by one to four years and was not collected, not analysed, or not acted on. Across the modelled outbreaks, <em>60 to 95 percent</em> of infections are attributed to the delay in detection and response — not to the drugs."},{"type":"source","text":"Glasgow 2015: 62.7% of cases averted had services scaled at detection · Athens: HIV among people who inject drugs rose from under 1% (2010) to 16.5% (2013); intervening two years earlier modelled to avert 1,110 cases and €35–53M"},{"type":"source","text":"Photo: Sarah Parvini / Los Angeles Times, Austin (2015) · <a href=\"https://www.latimes.com/nation/la-na-indiana-hiv-20150401-story.html\">report and caption</a> · Memorial shown concerns a separate overdose death, not an HIV-outbreak death."}],"cues":["Two sentences only. The numbers do the work.","The counterfactual is the point: almost all of that epidemic was the delay, not the drugs.","Do not editorialise. Let '<10' sit there.","The photo is a 2015 Austin community march; the memorial in frame is not an HIV-outbreak death. Keep the point on delayed public-health detection and response.","The maintainer confirmed Los Angeles Times image reuse permission is cleared for this public presentation."]},{"id":"reframe","act":"II","speaker":"S2","seconds":10,"theme":"atlas","blocks":[{"type":"swap","from":"Where are the drugs?","to":"Where does the harm land next?"},{"type":"sub","text":"Every other tool in this space answers the first question, for police. And every existing harm forecast is <em>autoregressive</em> — it predicts more of an epidemic a country already has. TRACE answers the second question, for public health, from outside: it forecasts harm in countries that have not had the epidemic yet, from the corridor that is about to open."}],"cues":["This swap is the innovation claim. Make it the loudest sentence in your section.","'Autoregressive' is the word that separates us: everyone else forecasts more of what a country already has.","The first question serves enforcement. The second serves prevention."],"layout":"center"},{"id":"terminal-hero","act":"II","speaker":"S2","seconds":14,"theme":"atlas","blocks":[{"type":"kicker","text":"One workspace. Every corridor."},{"type":"shot","sid":"route-map","aspect":"16/9","caption":"Atlas — modelled corridor arcs coloured by drug volume, {{counts.map_first_year}}–{{counts.map_last_observed}} observed with a {{counts.map_forecast_year}} forecast; the drug-coloured arrows are the estimated local-flow layer, labelled on the map as not observed","spec":"Full-bleed Atlas capture, 1440×960, Forecast on, all substances, estimated-flow arrows visible.","maxvh":70}],"cues":["This is the real thing, captured from the running app — say so.","Arc colour is modelled drug volume. The arrows are the estimated layer and the legend says so. One sentence, then let it breathe.","Do not narrate the UI. The live demo does that."]},{"id":"data-spine","act":"III","speaker":"S3","seconds":16,"theme":"atlas","blocks":[{"type":"kicker","text":"The data spine"},{"type":"statgrid","items":[{"value":"{{counts.indicators}}","label":"World Bank indicators","source":"Indicators API, sources 2 + 3, pulled programmatically into the SQLite v2 archive","viz":{"kind":"span","min":1960,"max":2025,"label":"1960–2025","from":1960,"to":2025}},{"value":"{{counts.economies}}","label":"economies","source":"SQLite v2 archive, 1960–2025; aggregates filtered out","viz":{"kind":"span","min":1960,"max":2025,"label":"1960–2025","from":1960,"to":2025}},{"value":"{{counts.ids_cases}}","label":"UNODC seizure cases","source":"Individual Drug Seizures, 2006–2024","viz":{"kind":"span","min":1960,"max":2025,"label":"2006–2024","from":2006,"to":2024}},{"value":"{{counts.corridors}}","label":"corridors modelled","source":"× 14 years, seizure-anchored allocation","viz":{"kind":"span","min":1960,"max":2025,"label":"2011–2024","from":2011,"to":2024}},{"value":"{{counts.oc_index}}","label":"countries, OC Index","source":"GI-TOC 2021 / 2023 / 2025 editions","viz":{"kind":"span","min":1960,"max":2025,"label":"3 editions","ticks":[2021,2023,2025]}},{"value":"{{counts.hri}}","label":"countries, harm reduction","source":"Harm Reduction International, Global State of Harm Reduction, 2025 update to key data","viz":{"kind":"span","min":1960,"max":2025,"label":"2025 update","ticks":[2025]}}]},{"type":"source","text":"Live evidence drilldown traces research and derived market values to formulas, source editions, exact input rows and original URLs; health and overdose records retain their method, date and status labels."}],"cues":["These are counts from our own pipeline — every one is checkable. Research and derived market values drill to formulas and exact source rows; health records keep their method labels.","The World Bank API is called programmatically with explicit source IDs. That's the track requirement and we meet it literally.","Don't read all six. Read two."]},{"id":"model","act":"III","speaker":"S3","seconds":16,"theme":"atlas","blocks":[{"type":"kicker","text":"Two models, and we report both"},{"type":"pipeline","steps":[{"step":"BASELINE","title":"PPML gravity","text":"Poisson pseudo-maximum-likelihood, the standard in trade economics. GDP, population, distance, contiguity, price gap."},{"step":"MAIN","title":"LightGBM hurdle","text":"(a) will this corridor be active next year, (b) how much moves if it is. Lagged volume, cultivation upstream, governance, logistics, OC Index, conflict. 46 features per route-year."},{"step":"EXPLAIN","title":"SHAP per corridor","text":"Every predicted shift comes with its drivers, in plain language, on the map."}]},{"type":"source","text":"Santos Silva & Tenreyro (2006) · Ke et al. (2017) · Lundberg & Lee (2017)"}],"cues":["The hurdle structure exists because most corridors are zero in most years. Say that — it shows you understand your own data.","SHAP is what turns a prediction into something a health ministry can act on."]},{"id":"reflex","act":"III","speaker":"S3","seconds":20,"theme":"atlas","blocks":[{"type":"kicker","text":"Live Wire · Reflex, our own Jev-style classifier"},{"type":"lines","scale":"m","items":["Official data is years late.","News is minutes late."]},{"type":"list","columns":3,"items":[{"title":"Ingest","text":"GDELT polled every 15 minutes, deduped, filtered to drug events worldwide."},{"title":"Classify","text":"Reflex — TRACE's own open System One model — turns each article into seven typed decisions in one batched pass. A 70M-parameter NLI cross-encoder is fine-tuned with log-loss, then temperature-scaled per primitive."},{"title":"Flag","text":"A confident event on a corridor the model gave under 10% probability is an anomaly — the model is wrong, and it says so on the map."}]},{"type":"viz","viz":{"kind":"bars","size":"sm","max":100,"items":[{"label":"Event type","value":98,"text":"98%","tone":"on"},{"label":"Destination","value":82,"text":"82%","tone":"on"},{"label":"Keyword mock","value":52,"text":"52%","tone":"off"}]},"caption":"Development benchmark · 100 synthetic, provisionally labelled headlines · not field validation"},{"type":"source","text":"Jev (TypeSafe, jev-1.13.0) had a waitlist, so we built Reflex behind the same interface: an NLI cross-encoder fine-tuned on a Colab T4 (about 7 minutes), temperature-scaled so its confidence is calibrated (ECE 0.02, the range reported for Jev). On 92 real published headlines, with grounding guardrails: drug 98%, destination 85%, zero invented countries or drugs, 5.1% false events. Jev swaps in once we have a key."}],"cues":["Why Reflex: Jev had a waitlist and no key. Same typed-question interface, open model, no TypeSafe code or weights.","Trained on a Colab T4 in about 7 min: held-out accuracy 48% untuned to 90%.","Real news, not synthetic: 92 headlines; grounding means every country and drug must appear in the text.","The anomaly flag: a confident seizure on a route the model gave under 10%."]},{"id":"honesty-method","act":"III","speaker":"S3","seconds":10,"theme":"atlas","blocks":[{"type":"kicker","text":"The objection we designed around"},{"type":"lines","scale":"m","items":["Seizures measure enforcement,","not trafficking."]},{"type":"viz","viz":{"kind":"stack","total":100,"items":[{"label":"seizures at both ends","value":30,"tone":0},{"label":"price rises along the route","value":20,"tone":1},{"label":"OC Index market score at both ends","value":20,"tone":2},{"label":"live news hits","value":10,"tone":3},{"label":"cultivation upstream","value":10,"tone":4},{"label":"documented UNODC corridor","value":10,"tone":5}],"label":"Corridor confidence, 0–100 points · seizures can supply at most 30"}},{"type":"sub","text":"Correct. So no corridor rests on seizures alone. Every edge carries a 0–100 confidence score built from six independent signals: seizures at both ends, a price gradient in the expected direction, OC Index market scores at both ends, live news hits, cultivation upstream, and a documented corridor. Detection bias is controlled with rule of law and customs efficiency. Low-confidence corridors are drawn faint, and we say so."},{"type":"source","text":"Every corridor carries a citation key, and all eleven resolve to a UNODC or EUDA publication — each checked for a live response and a matching title. A route-evidence API drills from any corridor on the map to the document it came from. Every known limitation is in docs/SYSTEM_DESIGN.md §5 and docs/BLOCKERS.md, not hidden."}],"cues":["Point at the bar: seizures are the grey 30. The other 70 points come from signals that don't depend on police catching anything.","Saying the weakness first is what makes the rest credible.","If pressed on provenance: click any corridor in the demo and it resolves to the UNODC or EUDA document behind it — and clicking an estimated arrow opens its whole chain, the corridors feeding it, and those corridors' published sources.","Hand off on strength: 'So — does it actually work?'"],"handoff":"So — does any of it actually work?"},{"id":"backtest","act":"IV","speaker":"S4","seconds":16,"theme":"atlas","blocks":[{"type":"kicker","text":"Backtest · trained through 2019, predicting 2020–{{counts.latest_year}}"},{"type":"compare","items":[{"label":"LightGBM hurdle","value":"{{metrics.hurdle_auc}}","pct":88,"tone":"up","note":"AUC, corridor activation"},{"label":"Same as last year","value":"0.82","pct":82,"tone":"dim","note":"AUC, persistence baseline"},{"label":"PPML gravity baseline","value":"{{metrics.gravity_auc}}","pct":58,"tone":"dim","note":"AUC, same corridors, same years"}]},{"type":"viz","viz":{"kind":"bars","size":"sm","max":1,"items":[{"label":"Meth","value":0.96,"text":"0.96","tone":"on"},{"label":"Heroin","value":0.92,"text":"0.92","tone":"on"},{"label":"Cannabis","value":0.89,"text":"0.89","tone":"on"},{"label":"Cocaine","value":0.79,"text":"0.79","tone":"on"}]},"caption":"Our model's AUC by drug, same 2020–2024 test"},{"type":"sub","text":"Routes are sticky, so “same as last year” is the honest baseline, and we beat it on all three measures: AUC, volume ranking (Spearman {{metrics.spearman}} vs 0.48) and growth calls (precision@20 {{metrics.precision_at_20}} vs 0.42). A corridor shift shows up a year ahead, not after a nine-year wait for prevalence data."}],"cues":["Say the persistence number out loud: 0.82. Beating 'same as last year' is the real test, and we clear it on all three metrics.","Don't say 'our model is accurate'. Say 'here is our model against the field standard, on held-out years'.","Then translate it: a year of warning against a nine-year wait. That is the number that matters to a health ministry.","The baseline existing at all is the credibility move."]},{"id":"close","act":"IV","speaker":"S4","seconds":8,"theme":"void","blocks":[{"type":"lines","scale":"l","tone":"dim","items":["Harm reduction usually arrives","after the crisis."]},{"type":"lines","scale":"xl","tone":"accent","items":["TRACE lets it arrive before."]}],"cues":["Pause before the last line. Then say it and stop.","Do not add anything after it."]},{"id":"handoff","act":"IV","speaker":"S4","seconds":2,"theme":"void","blocks":[{"type":"qr","src":"assets/qr-trace-site.svg","caption":"Scan to open the live site","url":"trace-atlas-gules.vercel.app"},{"type":"wordmark","text":"TRACE","small":true},{"type":"lines","scale":"m","items":["Let us show you."]},{"type":"source","text":"trace-atlas-gules.vercel.app · open it yourself, it is live"}],"cues":["Hit this and go straight into the demo. No pause, no 'any questions'.","The URL is on screen — tell the judges they can open it on their phones while we demo.","Terminal should already be open on the second machine.","Leave the QR code up during the demo handoff so judges can follow on their phones."],"layout":"split"}]},"data":{"project":{"name":"TRACE","one_liner":"A Bloomberg terminal for the global drug trade that predicts where the next drug crisis will hit, before it arrives.","tagline":"Early warning for the countries that never chose to be on the route."},"counts":{"indicators":"24","economies":"217","ids_cases":"2.3M","corridors":"676","oc_index":"193","hri":"197","risk_countries":"217","latest_year":"2024","first_year":"2011","sources":"8","map_first_year":"2006","map_last_observed":"2024","map_forecast_year":"2025"},"metrics":{"hurdle_auc":"0.88","gravity_auc":"0.58","afghan_hit":"9/13","sea_base":"5%","sea_pred":"14%","sea_actual":"13%","train_through":"2019","afghan_train_through":"2021","spearman":"0.58","precision_at_20":"0.48","afghan_right":"9","afghan_of":"13"},"charts":{"afghan":{"series":[{"id":"afg_cultivation","label":"Afghanistan","unit":"ha","points":[{"x":2015,"y":183000},{"x":2016,"y":201000},{"x":2017,"y":328000},{"x":2018,"y":263000},{"x":2019,"y":163000},{"x":2020,"y":224000},{"x":2021,"y":177000},{"x":2022,"y":233000},{"x":2023,"y":10800},{"x":2024,"y":12800},{"x":2025,"y":10200}]},{"id":"mmr_cultivation","label":"Myanmar","unit":"ha","points":[{"x":2015,"y":55500},{"x":2017,"y":41000},{"x":2018,"y":37300},{"x":2019,"y":33100},{"x":2020,"y":29500},{"x":2021,"y":30200},{"x":2022,"y":40100},{"x":2023,"y":47100},{"x":2024,"y":45200},{"x":2025,"y":53100}]}],"ban_year":2022,"title":"Afghanistan 2022 opium ban"}},"provenance":{"built_from":"defaults","metrics":"README.md (live run)","afghan":"contracts/fixtures/afghan_ban.json"},"people":{"total":3099,"organizations":229,"convicted":2031,"charged":456,"sanctioned":536,"reported":76},"screenshots":{"route-map":"screenshots/route-map.png","experiment":"screenshots/experiment.png","country-screen":"screenshots/country-screen.png","experiment-afghan":"screenshots/experiment-afghan.png","livewire":"screenshots/livewire.png","market-board":"screenshots/market-board.png","risk-board":"screenshots/risk-board.png","simulator":"screenshots/simulator.png","health-evidence":"screenshots/health-evidence.png","people":"screenshots/people.png"},"placeholders":[],"status":{"shipped":[{"label":"Spec, docs, handoff","owner":"planning session","status":"done"},{"label":"API contract + fixtures","owner":"backend","status":"done (`contracts/`)"},{"label":"backend scaffold","owner":"backend","status":"done (uv, Python 3.11, `trace` CLI)"},{"label":"World Bank ingest","owner":"backend","status":"done; now read from the SQLite v2 archive (24 indicators, 217 economies, 1960-2025)"},{"label":"external ingest (UNODC, OC Index, HRI, CEPII)","owner":"backend","status":"done (IDS 2.3M cases, WDR annex, OC Index x3, HRI 197 countries, CEPII; see BLOCKERS.md)"},{"label":"edges + confidence","owner":"backend","status":"done (676 corridors x 2011-2024, seizure-anchored allocation, 6-signal confidence)"},{"label":"route models + backtest + Afghan ban test","owner":"backend","status":"done, retrained on SQLite archive (hurdle AUC 0.88 vs gravity 0.58; Afghan ban 9/13 corridors, SEA share 5%->14% pred vs 13% actual)"},{"label":"spillover risk","owner":"backend","status":"done (217 countries x 2008-2025, HRI per edition; hypothesis not supported)"},{"label":"SQLite v2 migration","owner":"backend","status":"done (archive read-only + `derived.sqlite`; DuckDB removed)"},{"label":"Reflex (own System One model)","owner":"backend","status":"v0.2 shipped as the Live Wire classifier: 98% event type, 82% destination (mock 52%), ECE 0.02; see [REFLEX_SPEC.md](docs/REFLEX_SPEC.md)"},{"label":"export + API","owner":"backend","status":"done (precomputed JSON, FastAPI, contract tests)"},{"label":"Live Wire (mock Jev)","owner":"backend","status":"done (JevClassifier + mock, GDELT poller with replay fallback, REST + WS)"},{"label":"shock simulator","owner":"backend","status":"done (structured + plain-English shocks, command bar)"},{"label":"API deployment","owner":"backend","status":"done: live at https://trace-api-six.vercel.app (Vercel; keyword Live Wire classifier, backlog replay)"},{"label":"People API","owner":"backend","status":"done (`/api/people`, `/countries`, `/network`, `/{person_id}`; parity with the frontend route handlers)"},{"label":"Route evidence API","owner":"backend","status":"done (`/api/route-evidence`: 51 direct reported pairs, 234 interpreted corridors, 4 narrative claims; `evidence_ids`/`kg_basis` on route edges)"},{"label":"Evidence drilldown API","owner":"backend","status":"done (`/api/evidence/*`: 3,995 research and market values traced to formula, inputs and original cells; health and CDC overdose with the required labels)"},{"label":"Frontend shell + map","owner":"frontend","status":"done: live at https://trace-atlas-gules.vercel.app (atlas map with year slider and 2025 forecast, full-screen mode, drug filters, estimated local flows)"},{"label":"Country Screen + Risk Board","owner":"frontend","status":"done (risk watchlist and board, country inspector with routes, indicators, harm reduction and briefing)"},{"label":"Simulator, Live Wire, Market Board","owner":"frontend","status":"done (Scenarios tab with policy dates, Live Wire feed, Markets tab; Experiment tab for the Afghan ban test)"},{"label":"Merged database (`database_new`)","owner":"backend","status":"done: `backend/scripts/merge_databases.py` = canonical archive + derived API tables + route-evidence seeds (76 tables); uploaded to the team Drive folder as `database_new.sqlite.gz` + `database_new.json`"}],"pending":[],"frontend_built":true,"shipped_short":"Pipeline, models, backtests and Live Wire shipped; the site and the API are live in production","shipped_count":21,"pending_count":0},"git":{"sha":"93a51a3","subject":"deck: rebuild after Atlas flow refresh","when":"2026-09-27T10:46:06-04:00","count":"327"},"built_at":"2026-09-27 14:50 UTC","screenshot_snapshot":{"app":"trace-0.1.0","snapshot_utc":"2026-09-27 12:18 UTC"}}};